// Упражнение: в damage замените Math.max(0, args.amount - params.armor)
// на Math.max(0, args.amount * 2 - params.armor). Один удар — одно изменение HP.
// Native health/raycast, HUD и сохранение читают этот же state через явный адаптер.
const component = {
  name: "Health",
  parameters: {
    type: "object",
    properties: {
      initialHP: { type: "number", min: 1, default: 100, label: "Максимум / начальные HP" },
      armor: { type: "number", min: 0, default: 0, label: "Защита" },
    },
  },
  state: {
    type: "object",
    properties: {
      hp: { type: "number", min: 0, default: 100, label: "HP" },
      maxHP: { type: "number", min: 1, default: 100, label: "Максимум HP" },
      dead: { type: "boolean", default: false, label: "Погиб" },
    },
  },
  stateFromParameters: { hp: "initialHP", maxHP: "initialHP" },
  references: {
    type: "object",
    properties: {
      deathReaction: {
        type: "reference",
        referenceType: "mechanic",
        optional: true,
        label: "Реакция на смерть",
      },
    },
  },
  methods: {
    damage: {
      name: "Нанести урон",
      parameters: {
        type: "object",
        properties: { amount: { type: "number", min: 0, label: "Урон" } },
      },
      result: { type: "boolean" },
      async run({ args, params, state, engine, self, owner }) {
        if (state.dead) return false;
        const damage = Math.max(0, args.amount - params.armor);
        state.hp = Math.max(0, state.hp - damage);
        const died = state.hp === 0;
        state.dead = died;
        await engine.operation("sacura.health.publish", { owner, signal: "hit", amount: damage });
        if (died) {
          await engine.operation("sacura.health.publish", { owner, signal: "death" });
          await engine.invoke(self, "die", {});
        }
        await engine.operation("sacura.game.commit", {});
        return true;
      },
    },
    heal: {
      name: "Лечить",
      parameters: {
        type: "object",
        properties: { amount: { type: "number", min: 0, label: "Лечение" } },
      },
      result: { type: "boolean" },
      async run({ args, state, engine }) {
        if (state.dead) return false;
        state.hp = Math.min(state.maxHP, state.hp + args.amount);
        await engine.operation("sacura.game.commit", {});
        return true;
      },
    },
    die: {
      name: "Обработать смерть",
      result: { type: "void" },
      async run({ refs, engine, owner }) {
        if (refs.deathReaction)
          await engine.invoke(refs.deathReaction, "onDeath", { defeated: owner });
      },
    },
  },
};

// Упражнения: измените damage * 1 на damage * 2; замените cost = 1 на cost = 2.
// Только геометрия луча/снаряда и визуализация являются native-примитивами.
const component = {
  name: "Weapon",
  parameters: {
    type: "object",
    properties: {
      damage: { type: "number", min: 0, default: 25, label: "Базовый урон" },
      magazine: { type: "integer", min: 1, default: 6, label: "Ёмкость магазина" },
      reserve: { type: "integer", min: 0, default: 30, label: "Начальный запас" },
      cooldown: { type: "number", min: 0, default: 0.3, label: "Пауза выстрела" },
      reloadTime: { type: "number", min: 0, default: 1, label: "Время перезарядки" },
      range: { type: "number", min: 0, default: 40, label: "Дальность" },
      mode: {
        type: "string",
        enum: ["hitscan", "projectile"],
        default: "hitscan",
        label: "Луч / снаряд",
      },
      projectileSpeed: { type: "number", min: 0, default: 20, label: "Скорость снаряда" },
      recoil: { type: "number", min: 0, default: 0.025, label: "Отдача" },
    },
  },
  state: {
    type: "object",
    properties: {
      ammo: { type: "integer", min: 0, default: 6, label: "В магазине" },
      reserve: { type: "integer", min: 0, default: 30, label: "В запасе" },
      nextShot: { type: "number", default: 0 },
      reloadUntil: { type: "number", default: 0 },
      enabled: { type: "boolean", default: true },
    },
  },
  stateFromParameters: { ammo: "magazine", reserve: "reserve" },
  references: {
    type: "object",
    properties: {
      record: {
        type: "reference",
        referenceType: "weapon",
        label: "Native-геометрия этого оружия",
      },
    },
  },
  methods: {
    select: {
      name: "Выбрать это оружие",
      async run({ owner, refs, engine }) {
        await engine.operation("sacura.weapon.select", { owner, weapon: refs.record });
      },
    },
    shoot: {
      name: "Выстрелить",
      parameters: {
        type: "object",
        properties: {
          origin: { type: "vector", size: 3, optional: true, label: "Начало луча" },
          direction: { type: "vector", size: 3, optional: true, label: "Направление луча" },
        },
      },
      result: { type: "boolean" },
      async run({ args, params, state, refs, owner, engine }) {
        const clock = await engine.operation("sacura.game.clock", {}),
          health = await engine.operation("sacura.health.read", { owner });
        const cost = 1;
        const aim = await engine.operation("sacura.weapon.aim", {
          owner,
          weapon: refs.record,
          ...args,
        });
        if (
          !aim.valid ||
          !state.enabled ||
          health.dead ||
          state.ammo < cost ||
          clock < state.nextShot ||
          clock < state.reloadUntil
        )
          return false;
        state.ammo -= cost;
        state.nextShot = clock + params.cooldown;
        const damage = params.damage * 1;
        if (params.mode === "projectile")
          await engine.operation("sacura.weapon.projectile", {
            owner,
            origin: aim.origin,
            direction: aim.direction,
            range: params.range,
            speed: params.projectileSpeed,
            damage,
          });
        else {
          const hit = await engine.operation("sacura.weapon.raycast", {
            owner,
            origin: aim.origin,
            direction: aim.direction,
            range: params.range,
          });
          await engine.operation("sacura.weapon.tracer", { from: aim.origin, to: hit.point });
          if (hit.hit)
            await engine.operation("sacura.health.damage", { owner: hit.target, amount: damage });
        }
        await engine.operation("sacura.weapon.recoil", { owner, amount: params.recoil });
        await engine.operation("sacura.game.commit", {});
        return true;
      },
    },
    reload: {
      name: "Перезарядить",
      result: { type: "boolean" },
      async run({ params, state, engine, owner }) {
        const clock = await engine.operation("sacura.game.clock", {}),
          health = await engine.operation("sacura.health.read", { owner });
        if (
          !state.enabled ||
          health.dead ||
          state.ammo >= params.magazine ||
          state.reserve <= 0 ||
          state.reloadUntil > clock
        )
          return false;
        state.reloadUntil = clock + params.reloadTime;
        await engine.wait(params.reloadTime);
        const amount = Math.min(params.magazine - state.ammo, state.reserve);
        state.ammo += amount;
        state.reserve -= amount;
        state.reloadUntil = 0;
        await engine.operation("sacura.game.commit", {});
        return true;
      },
    },
  },
};

// Откройте onDeath: изменяйте награду/победу здесь, а не в скрытом preset.
const component = {
  name: "DeathReaction",
  parameters: {
    type: "object",
    properties: { hide: { type: "boolean", default: true, label: "Скрыть после смерти" } },
  },
  state: {
    type: "object",
    properties: { handled: { type: "boolean", default: false, label: "Смерть обработана" } },
  },
  references: {
    type: "object",
    properties: {
      reward: { type: "reference", referenceType: "mechanic", optional: true, label: "Награда" },
      objective: { type: "reference", referenceType: "mechanic", optional: true, label: "Задание" },
      behavior: {
        type: "reference",
        referenceType: "mechanic",
        optional: true,
        label: "Дерево погибшего",
      },
      battle: {
        type: "reference",
        referenceType: "mechanic",
        optional: true,
        label: "Остановить бой",
      },
      ending: {
        type: "reference",
        referenceType: "beat",
        optional: true,
        label: "Финал после смерти",
      },
    },
  },
  methods: {
    onDeath: {
      name: "Реакция на смерть",
      parameters: {
        type: "object",
        properties: {
          defeated: { type: "reference", referenceType: "object", label: "Погибший объект" },
        },
      },
      async run({ args, params, state, refs, engine }) {
        if (state.handled) return;
        state.handled = true;
        await engine.operation("sacura.movement.enabled", { owner: args.defeated, enabled: false });
        if (params.hide)
          await engine.operation("sacura.object.visible", {
            object: args.defeated,
            visible: false,
          });
        if (refs.reward) await engine.invoke(refs.reward, "award", {});
        if (refs.objective) await engine.invoke(refs.objective, "check", {});
        if (refs.ending) await engine.operation("sacura.story.enter", { beat: refs.ending });
        if (refs.behavior)
          await engine.operation("sacura.component.start", {
            instance: refs.behavior,
            methodId: "stop",
            args: {},
            lifetime: "component",
            lifetimeOwner: refs.behavior,
          });
        if (refs.battle)
          await engine.operation("sacura.component.start", {
            instance: refs.battle,
            methodId: "stop",
            args: {},
            lifetime: "component",
            lifetimeOwner: refs.battle,
          });
      },
    },
  },
};

// Упражнение: в chase замените direction на direction.map(x => -x): враг отступает.
// Behavior Tree выбирает эти публичные методы. Цель/HP/дальность — ссылки и параметры
// конкретного экземпляра; дерево и исходник общие для всех противников.
const component = {
  name: "EnemyAgent",
  parameters: {
    type: "object",
    properties: {
      detection: { type: "number", min: 0, default: 30, label: "Обнаружение" },
      range: { type: "number", min: 0, default: 1.8, label: "Дальность удара" },
      damage: { type: "number", min: 0, default: 9, label: "Урон" },
      windup: { type: "number", min: 0, default: 0.3, label: "Подготовка удара" },
      interval: { type: "number", min: 0, default: 1, label: "Между ударами" },
    },
  },
  state: {
    type: "object",
    properties: { nextAttack: { type: "number", default: 0, label: "Следующая атака" } },
  },
  references: {
    type: "object",
    properties: {
      target: { type: "reference", referenceType: "object", label: "Цель" },
      targetHealth: { type: "reference", referenceType: "mechanic", label: "Здоровье цели" },
    },
  },
  methods: {
    attack: {
      name: "Атаковать",
      result: { type: "boolean" },
      async run({ params, state, refs, owner, engine }) {
        const selfHealth = await engine.operation("sacura.health.read", { owner }),
          seen = await engine.operation("sacura.spatial.observe", { owner, target: refs.target });
        if (selfHealth.dead || !seen.available || !seen.lineOfSight || seen.distance > params.range)
          return false;
        if (seen.clock < state.nextAttack) {
          await engine.wait(0.1);
          return true;
        }
        await engine.wait(params.windup);
        const now = await engine.operation("sacura.spatial.observe", {
          owner,
          target: refs.target,
        });
        const currentHealth = await engine.operation("sacura.health.read", { owner });
        if (
          !currentHealth.dead &&
          now.available &&
          now.lineOfSight &&
          now.distance <= params.range
        ) {
          state.nextAttack = now.clock + params.interval;
          await engine.invoke(refs.targetHealth, "damage", { amount: params.damage });
        }
        return true;
      },
    },
    chase: {
      name: "Преследовать",
      result: { type: "boolean" },
      async run({ params, refs, owner, engine }) {
        const health = await engine.operation("sacura.health.read", { owner }),
          seen = await engine.operation("sacura.spatial.observe", { owner, target: refs.target });
        if (health.dead || !seen.available || seen.distance > params.detection) return false;
        const direction = seen.direction;
        await engine.operation("sacura.movement.direction", { owner, direction });
        await engine.wait(0.1);
        return true;
      },
    },
    idle: {
      name: "Ждать",
      result: { type: "boolean" },
      async run({ engine }) {
        await engine.wait(0.1);
        return true;
      },
    },
  },
};

// Ввод адресует Loadout; Fire/Reload вызывают выбранный экземпляр Weapon.
// Это ссылка на конкретное подключение, а не «первое оружие такого типа».
const component = {
  name: "Loadout",
  parameters: {
    type: "object",
    properties: {
      initial: { type: "reference", referenceType: "mechanic", label: "Начальное оружие · Weapon" },
    },
  },
  state: {
    type: "object",
    properties: {
      selected: {
        type: "reference",
        referenceType: "mechanic",
        optional: true,
        label: "Выбранное оружие",
      },
    },
  },
  stateFromParameters: { selected: "initial" },
  lifecycle: { initialize: "prepare" },
  methods: {
    prepare: {
      name: "Подготовить выбор",
      async run({ state, engine }) {
        await engine.invoke(state.selected, "select", {});
      },
    },
    select: {
      name: "Выбрать оружие",
      parameters: {
        type: "object",
        properties: {
          weapon: { type: "reference", referenceType: "mechanic", label: "Конкретное оружие" },
        },
      },
      async run({ args, state, engine }) {
        await engine.invoke(args.weapon, "select", {});
        state.selected = args.weapon;
      },
    },
    fire: {
      name: "Огонь выбранным оружием",
      result: { type: "boolean" },
      async run({ state, engine }) {
        return await engine.invoke(state.selected, "shoot", {});
      },
    },
    reload: {
      name: "Перезарядить выбранное оружие",
      result: { type: "boolean" },
      async run({ state, engine }) {
        return await engine.invoke(state.selected, "reload", {});
      },
    },
  },
};

// Лечение и расход предмета открыты: сначала проверяем Health, затем расходуем одну аптечку.
const component = {
  name: "Medkit",
  parameters: {
    type: "object",
    properties: { heal: { type: "number", min: 0, default: 35, label: "Восстановить HP" } },
  },
  references: {
    type: "object",
    properties: {
      health: { type: "reference", referenceType: "mechanic", label: "Здоровье получателя" },
      inventory: { type: "reference", referenceType: "object", label: "Владелец инвентаря" },
      item: { type: "reference", referenceType: "item", label: "Предмет аптечки" },
    },
  },
  methods: {
    use: {
      name: "Использовать аптечку",
      result: { type: "boolean" },
      async run({ params, refs, engine }) {
        if (
          (await engine.operation("sacura.inventory.count", {
            owner: refs.inventory,
            item: refs.item,
          })) < 1
        )
          return false;
        const healed = await engine.invoke(refs.health, "heal", { amount: params.heal });
        if (!healed) return false;
        await engine.operation("sacura.inventory.remove", {
          owner: refs.inventory,
          item: refs.item,
          count: 1,
        });
        await engine.operation("sacura.game.message", { message: "Здоровье восстановлено" });
        return true;
      },
    },
  },
};

// Предмет/получатель назначаются ссылками в инспекторе. Без имён объектов в коде.
const component = {
  name: "Pickup",
  parameters: {
    type: "object",
    properties: { count: { type: "integer", min: 1, default: 1, label: "Количество" } },
  },
  state: {
    type: "object",
    properties: { collected: { type: "boolean", default: false, label: "Получен" } },
  },
  references: {
    type: "object",
    properties: {
      inventory: {
        type: "union",
        variants: [
          { type: "reference", referenceType: "object", label: "Объект" },
          { type: "reference", referenceType: "project", label: "Проект" },
        ],
      },
      item: { type: "reference", referenceType: "item", label: "Предмет" },
    },
  },
  methods: {
    pickup: {
      name: "Подобрать",
      result: { type: "boolean" },
      async run({ params, state, refs, engine, owner }) {
        if (state.collected) return false;
        state.collected = true;
        try {
          await engine.operation("sacura.inventory.add", {
            owner: refs.inventory,
            item: refs.item,
            count: params.count,
          });
        } catch (error) {
          state.collected = false;
          throw error;
        }
        await engine.operation("sacura.object.visible", { object: owner, visible: false });
        await engine.operation("sacura.game.message", { message: "Предмет в инвентаре" });
        return true;
      },
    },
  },
};

// Цели — коллекция или тег в параметрах. Количество противников в код не зашито.
const component = {
  name: "Objective",
  parameters: {
    type: "object",
    properties: {
      targets: {
        type: "collection",
        items: { type: "reference", referenceType: "object" },
        default: [],
        label: "Цели задания · объекты / тег",
      },
    },
  },
  state: {
    type: "object",
    properties: {
      active: { type: "boolean", default: false },
      complete: { type: "boolean", default: false },
    },
  },
  references: {
    type: "object",
    properties: {
      battle: {
        type: "reference",
        referenceType: "mechanic",
        optional: true,
        label: "Остановить бой",
      },
      victory: { type: "reference", referenceType: "beat", label: "Победный финал" },
    },
  },
  methods: {
    begin: {
      name: "Начать задание",
      run({ state }) {
        state.active = true;
      },
    },
    check: {
      name: "Проверить задание",
      result: { type: "boolean" },
      async run({ params, state, refs, engine }) {
        if (!state.active || state.complete) return false;
        if (!(await engine.operation("sacura.health.all-dead", { objects: params.targets })))
          return false;
        state.complete = true;
        if (refs.battle)
          await engine.operation("sacura.component.start", {
            instance: refs.battle,
            methodId: "stop",
            args: {},
            lifetime: "component",
            lifetimeOwner: refs.battle,
          });
        await engine.operation("sacura.signal.victory", {});
        await engine.operation("sacura.story.enter", { beat: refs.victory });
        return true;
      },
    },
  },
};

// История явно запускает Run с lifetime=scene. Компоненты Health сами бой не начинают.
// Обычная следующая реплика не отменяет Run. Stop/отмена владельца останавливают дочерние BT.
const component = {
  name: "Battle",
  state: {
    type: "object",
    properties: { running: { type: "boolean", default: false, label: "Бой идёт" } },
  },
  references: {
    type: "object",
    properties: {
      behaviors: {
        type: "collection",
        items: { type: "reference", referenceType: "mechanic" },
        default: [],
        label: "Деревья противников",
      },
      objective: { type: "reference", referenceType: "mechanic", label: "Задание" },
    },
  },
  lifecycle: { disable: "stop" },
  methods: {
    run: {
      name: "Запустить бой",
      async run({ state, refs, engine }) {
        if (state.running) return;
        state.running = true;
        await engine.invoke(refs.objective, "begin", {});
        try {
          await Promise.all(refs.behaviors.map((instance) => engine.invoke(instance, "start", {})));
        } finally {
          state.running = false;
        }
      },
    },
    stop: {
      name: "Остановить бой",
      async run({ state, refs, engine }) {
        state.running = false;
        for (const instance of refs.behaviors) await engine.invoke(instance, "stop", {});
      },
    },
  },
};

// Откройте Add: измените умножение на params.step — результат изменится во всех вызовах.
// Один исходник, независимое value у каждого подключения.
const component = {
  name: "Counter",
  parameters: {
    type: "object",
    properties: {
      initial: { type: "number", default: 0, label: "Начальное значение" },
      storySource: {
        type: "boolean",
        default: false,
        label: "Менять источник постоянной привязки явно",
      },
      step: { type: "number", default: 1, label: "Множитель изменения" },
    },
  },
  state: {
    type: "object",
    properties: { value: { type: "number", default: 0, label: "Текущее значение" } },
  },
  stateFromParameters: { value: "initial" },
  signals: {
    changed: {
      name: "Значение изменилось",
      payloadSchema: { type: "object", properties: { value: { type: "number" } } },
    },
  },
  methods: {
    add: {
      name: "Добавить",
      parameters: {
        type: "object",
        properties: { amount: { type: "number", default: 1, label: "Количество" } },
      },
      result: { type: "number" },
      async run({ args, params, state, engine }) {
        const next = state.value + args.amount * params.step;
        if (params.storySource) await engine.writeBinding("value", next);
        else state.value = next;
        await engine.emit("changed", { value: state.value });
        return state.value;
      },
    },
    read: {
      name: "Прочитать",
      result: { type: "number" },
      run({ state }) {
        return state.value;
      },
    },
    multiply: {
      name: "Умножить",
      parameters: {
        type: "object",
        properties: { factor: { type: "number", default: 2, label: "Множитель" } },
      },
      result: { type: "number" },
      async run({ args, params, state, engine }) {
        const next = state.value * args.factor;
        if (params.storySource) await engine.writeBinding("value", next);
        else state.value = next;
        await engine.emit("changed", { value: state.value });
        return state.value;
      },
    },
  },
};

// Упражнение: замените base * multiplier на base * multiplier + 5.
